messages.content:
{
  "response": {
    "note": "We will proceed with an escalation to Security for a formal incident review and will provide sanitized, leadership-facing findings. To move quickly, please provide the scope details and security contact information requested below. We will schedule a real-time bridge call with leadership and Security once we have availability.",
    "information_needed": [
      {
        "category": "Affected assets",
        "fields": [
          "asset_id / asset_name",
          "environment (prod / non-prod / staging)",
          "owner / responsible team",
          "asset_type (e.g., server, webhook, datastore, API gateway, container, gateway, frontend)",
          "location / region",
          "criticality (high / medium / low)"
        ]
      },
      {
        "category": "Affected systems and services",
        "fields": [
          "system_name / service_name",
          "environment",
          "owner / service owner",
          "dependencies",
          "uptime status (expected vs observed during incident)"
        ]
      },
      {
        "category": "Webhooks and integrations",
        "fields": [
          "webhook_id / name",
          "provider",
          "endpoint_uri (masked in external communication)",
          "signing_method (e.g., HMAC-SHA256)",
          "last_activity_timestamp",
          "rotation_status (rotated / pending / not rotated)",
          "ip_allowlist_status"
        ]
      },
      {
        "category": "Incident timeframe",
        "fields": [
          "start_time (with time zone)",
          "end_time (with time zone, if applicable)",
          "recurrences / repeats (if any)"
        ]
      },
      {
        "category": "Data exposure scope (sanitized)",
        "fields": [
          "data_categories (e.g., PII, PHI, credentials, financial data, secrets)",
          "data_locations (where data resides, e.g., data store names, regions)",
          "potential_exposure (yes / no)",
          "sanitized_examples (non-sensitive samples or placeholders)"
        ]
      },
      {
        "category": "Indicators of compromise (IOCs)",
        "fields": [
          "ioc_list (domains, IPs, file hashes, user agents)",
          "first_seen / last_seen timestamps",
          "detection_methods"
        ]
      },
      {
        "category": "Access control and credentials",
        "fields": [
          "accounts affected",
          "roles / permissions changed",
          "tokens / secrets rotated or not",
          "MFA status (enabled / enforced)"
        ]
      },
      {
        "category": "Deployments, patches, and changes",
        "fields": [
          "patch_id / release_name",
          "deployment_time",
          "status (completed / in progress / rolled back)",
          "rollback_plan"
        ]
      },
      {
        "category": "Evidence handling and retention",
        "fields": [
          "log_sources involved",
          "log retention policy",
          "chain_of_custody identifiers",
          "where evidence is stored"
        ]
      },
      {
        "category": "Sanitized data sharing constraints",
        "fields": [
          "approved data elements for sharing",
          "security approval path",
          "security contact for handoff"
        ]
      }
    ],
    "security_escalation_plan": {
      "summary": "Escalate to Security for formal incident review and sanitized leadership-facing reporting.",
      "expected_output": [
        "sanitized incident findings report",
        "timeline of events",
        "root cause analysis (sanitized)",
        "remediation actions and owners",
        "residual risk assessment",
        "recommended monitoring and controls"
      ],
      "timeline": " sanitized findings will be provided within 1-2 business days after Security completes its review; updates will be provided as appropriate"
    },
    "bridge_call_proposal": {
      "participants": ["Leadership", "Security"],
      "duration_minutes": 60,
      "availability_request": "Please share your time zone and two to three 60-minute windows in the next 5 business days. We will coordinate with Security and leadership to finalize.",
      "agenda": [
        "Sanitized findings overview",
        "Remediation status and next steps",
        "Sanitized data disclosures (if any)",
        "Actions, owners, and timeline"
      ]
    },
    "next_steps_for_customer": [
      "Provide the scope details using the information fields above.",
      "Share security contact(s) (name, role, email, phone) for handoff.",
      "Provide your availability in your time zone for the bridge call (two to three 60-minute windows).",
      "Confirm that you want us to proceed with Security escalation now."
    ],
    "data_handling_commitment": "All shared information will be sanitized for external communication. No raw logs or credential dumps will be disclosed externally without secure governance approval."
  }
}

